    94	  const { locale: siteLocale } = useMultiSite() as { locale?: { id: string } };
    95	  const locale = siteLocale?.id || CONTENTFUL_FALLBACK_LOCALE;
    96	  const { res } = useServerContext();
    97	  // Preview requests use the CPA host+token only when a token is configured; otherwise the page
    98	  // renders in normal delivery mode. A preview request WITHOUT a token is handled explicitly
    99	  // below (404 + noindex) — it never silently falls back to delivery.
   100	  const {
   101	    client,
   102	    previewUnavailable,
   103	    isPreview: effectivePreview,
   104	  } = useContentfulClient({
   105	    preview: isPreview,
   106	  });
   107	
   108	  // @contentful/experiences-sdk-react's useFetchBySlug (called inside ExperienceFetch) branches its
   109	  // initial canvas-mode state on `typeof window !== 'undefined'`, which differs between the SSR pass
   110	  // and the client's first hydration pass when this page loads inside Contentful Studio's Experience
   111	  // Builder canvas iframe — a structural hydration mismatch (React errors #418/#423) that discards the
   112	  // whole render. Delaying ExperienceFetch's mount until after hydration means the server and the
   113	  // client's first paint both render the same Spinner placeholder below, so there's nothing to
   114	  // mismatch — useFetchBySlug then only ever runs in a pure client-side render pass.
   115	  //
   116	  // Only applied when `isEditorCanvas` (the `expEditorMode` query param Contentful Studio's canvas
   117	  // appends to its iframe URL — visible server-side via the query string, unlike `window`/iframe
   118	  // detection) is set — a normal storefront request never sets it, so it keeps rendering the real
   119	  // experience content in the initial SSR response as before, per the perf budget in AGENTS.md.
   120	  const [mounted, setMounted] = useState(false);
   121	  useEffect(() => {
   122	    if (isEditorCanvas) {
   123	      setMounted(true);
   124	    }
   125	  }, [isEditorCanvas]);
   126	
   127	  // Preview requested but no CPA token (the non-prod gate): fail explicitly with a 404 and
   128	  // noindex, mirroring the /preview route, so a `?preview` URL is never an indexable 200 on prod.
   129	  if (previewUnavailable) {
   130	    if (res) {
   131	      res.status(404);
   132	    }
   133	    return (
   134	      <>
   135	        <Seo noIndex />
   136	        <Box p={8}>
   137	          <Text color="red.500">Preview is not enabled in this environment.</Text>
   138	        </Box>
   139	      </>
   140	    );
   141	  }
   142	
   143	  if (!client) {
   144	    // Contentful config missing = server misconfiguration, not a missing page: 500 (not 404),
   145	    // + noindex so the error state is never indexed if it ever surfaces in production.
   146	    if (res) {
   147	      res.status(500);
   148	    }
   149	    return (
   150	      <>
   151	        <Seo noIndex />
   152	        <Box p={8}>
   153	          <Text color="red.500">Contentful configuration is missing — cannot render this page.</Text>
   154	        </Box>
   155	      </>
   156	    );
   157	  }
   158	
   159	  if (isEditorCanvas && !mounted) {
   160	    return (
   161	      <Box p={8} display="flex" justifyContent="center">
   162	        <Spinner size="xl" />
   163	      </Box>
   164	    );
   165	  }
   166	
   167	  return <ExperienceFetch client={client} slug={slug} locale={locale} isPreview={effectivePreview} />;
   168	};
   169	
   170	const Experience = () => {
   171	  const { pathname, search } = useLocation();
   172	  const slug = pathname.slice(1); // strip leading '/'
   173	  const params = new URLSearchParams(search);
   174	  const isPreview = params.has('preview');
   175	  // Contentful Studio's Experience Builder canvas appends this to its iframe URL — see the
   176	  // hydration-workaround comment in ExperiencePage for why this needs to be visible server-side.
   177	  const isEditorCanvas = params.has('expEditorMode');
   178	
   179	  return <ExperiencePage slug={slug} isPreview={isPreview} isEditorCanvas={isEditorCanvas} />;
   180	};
   181	
   182	Experience.getTemplateName = () => 'experience';
   183	
   184	export default Experience;

