import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { useContentfulClient } from 'app/hooks/useContentfulClient';
import type { FooterConfigEntry, FooterNavGroupEntry, LinkEntry, RegionEntry } from 'app/types/contentful';
import FooterContainer, { scopeToRegion } from './index';

// See footerNavColumn/index.test.tsx's identical mock for why: ZimmIcon pulls in the base SFCC
// icons barrel, which throws under Vitest (SVG imports resolve to raw path strings here).
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
  ZimmIcon: () => null,
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
  default: vi.fn(),
}));

vi.mock('app/hooks/useContentfulClient', () => ({
  useContentfulClient: vi.fn(),
}));

// FooterContainer no longer calls useUiCopy() itself (BottomBar/ZimmSubscribeSection source
// their own microcopy directly — see their own test files). With no UiCopyProvider mounted in
// this render tree, useUiCopy() gracefully degrades to fallback-only text on its own, so no
// mock is needed here for that to behave correctly.

const mockUseMultiSite = vi.mocked(useMultiSite);
const mockUseContentfulClient = vi.mocked(useContentfulClient);

// ---------------------------------------------------------------------------
// Fixture builders
// ---------------------------------------------------------------------------

const makeRegion = (siteId: string): RegionEntry => ({
  sys: { id: `region-${siteId}`, contentType: { sys: { id: 'region' } } },
  fields: { siteId, label: siteId },
});

const makeLink = (id: string, label: string, regions?: RegionEntry[]): LinkEntry => ({
  sys: { id, contentType: { sys: { id: 'link' } } },
  fields: { label, href: '#', regions },
});

const makeGroup = (id: string, links: LinkEntry[]): FooterNavGroupEntry => ({
  sys: { id, contentType: { sys: { id: 'footerNavGroup' } } },
  fields: { heading: id, links },
});

const makeConfig = (id: string, overrides: Partial<FooterConfigEntry['fields']> = {}): FooterConfigEntry => ({
  sys: { id, contentType: { sys: { id: 'footerConfig' } } },
  fields: {
    internalTitle: id,
    navGroups: [makeGroup('group-about', [makeLink('link-1', 'Our Story')])],
    ...overrides,
  },
});

// ---------------------------------------------------------------------------

